ession term \u2014 Focal length: Lens magnification."], ["Prime lens","Profession term \u2014 Prime lens: Fixed focal length."], ["Zoom lens","Profession term \u2014 Zoom lens: Variable focal length."], ["Second shooter","Profession term \u2014 Second shooter: The assistant photographer."], ["Shot list","Profession term \u2014 Shot list: Must-have images."], ["Culling","Profession term \u2014 Culling: Selecting keepers."], ["Preset","Profession term \u2014 Preset: One-click editing starting points."], ["3-2-1 backup","Profession term \u2014 3-2-1 backup: Three copies, two media, one offsite."], ["Model release","Profession term \u2014 Model release: Permission to use likenesses."], ["Usage rights","Profession term \u2014 Usage rights: How clients may use images."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
